export function initMentorVoice(){
 const section=document.createElement('section');section.className='sheet mentor-voice';section.id='mentor-voice';
 section.innerHTML=`<p class="eyebrow">前言 / 导师的声音</p><h2>上传导师音视频</h2><p>先上传导师原视频即可。少量背景音乐会标记为待分离，之后挑选清晰人声。前言按申请导师分别准备，不必现在填写。</p><label class="file-pick">选择音频或视频<input id="mentor-file" type="file" accept=".mp3,.wav,.m4a,.mp4,.mov,.webm,.ogg,.flac"></label><p id="mentor-filename" class="muted">支持 MP3、WAV、M4A、MP4、MOV、WebM、Ogg、FLAC，最大 200MB。</p><video id="mentor-preview" controls playsinline hidden></video><label for="mentor-preface">前言补充要求（可留空）</label><textarea id="mentor-preface" maxlength="3000" rows="5" placeholder="可以留空；将根据申请导师的研究资料分别拟写，确认文稿后再生成语音。"></textarea><label class="consent"><input id="mentor-consent" type="checkbox">导师已明确同意复刻她的音色，并用于本项目演示前言</label><div class="actions"><button id="mentor-upload" disabled>上传导师素材</button></div><div id="mentor-progress-wrap" hidden><progress id="mentor-progress" max="100" value="0"></progress><span id="mentor-percent"></span></div><p id="mentor-message" role="status" aria-live="polite"></p><ul id="mentor-saved"></ul><p class="muted">此处保存素材和前言，尚未生成或启用导师音色。生成试听确认后，前言才会接入演示。</p>`;
 document.querySelector('footer').before(section);
 const $=s=>section.querySelector(s);let file=null,objectURL='',busy=false,uploadId='',uploaded=false;
 const draftKey='mentor-preface-draft';$('#mentor-preface').value=localStorage.getItem(draftKey)||'';
 // Keep the action visible and responsive. A disabled primary button leaves no
 // clue on touch devices about which prerequisite is missing.
 function controls(){ $('#mentor-upload').disabled=busy;for(const id of ['#mentor-file','#mentor-consent','#mentor-preface'])$(id).disabled=busy; }
 const say=t=>$('#mentor-message').textContent=t;
 async function previewTrial(item,button,variant=''){const label=button.textContent;button.disabled=true;button.textContent='正在载入试听…';try{const r=await fetch(`/api/voice-reference/mentor/${item.id}/trial${variant?`?variant=${variant}`:''}`);if(!r.ok){const d=await r.json();throw Error(d.error||'试听暂不可用。');}const blob=await r.blob();if(!blob.size)throw Error('试听音频为空，请稍后重试。');const prior=button.parentElement.querySelector('.mentor-audio');if(prior){URL.revokeObjectURL(prior.src);prior.remove();}const audio=document.createElement('audio');audio.className='mentor-audio';audio.controls=true;audio.preload='metadata';audio.playsInline=true;audio.src=URL.createObjectURL(blob);audio.onended=audio.onerror=()=>{if(audio.error)say('播放器未能解码这段音频。');};button.after(audio);say(variant==='cosy'?'CosyVoice 对照试听已载入，请点播放器的三角按钮播放。':'试听已载入，请点播放器的三角按钮播放。');}catch(e){say(e.message||'试听暂时无法载入。');}finally{button.disabled=false;button.textContent=label;}}
 async function list(){try{const r=await fetch('/api/voice-reference');const d=await r.json();if(!r.ok)throw Error(d.error);const keepPreview=[...$('#mentor-saved').querySelectorAll('audio')].some(a=>!a.paused);if(!keepPreview){$('#mentor-saved').replaceChildren();for(const item of d.mentorRecordings||[]){const li=document.createElement('li');const label=document.createElement('span');const when=item.created?new Date(item.created*1000).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';label.textContent=`${item.name}${when?`（${when}）`:''} — ${item.status}`;li.append(label);if(item.trialReady){const b=document.createElement('button');b.type='button';b.className='mentor-trial';b.textContent='播放试听';b.onclick=()=>previewTrial(item,b);li.append(b);}if(item.cosyTrialReady){const b=document.createElement('button');b.type='button';b.className='mentor-trial';b.textContent='CosyVoice 对照试听';b.onclick=()=>previewTrial(item,b,'cosy');li.append(b);}if(item.hqTrialReady){const b=document.createElement('button');b.type='button';b.className='mentor-trial';b.textContent='高保真试听';b.onclick=()=>previewTrial(item,b,'hq');li.append(b);}if(item.fullTrialReady){const b=document.createElement('button');b.type='button';b.className='mentor-trial';b.textContent='声学全参数训练试听';b.onclick=()=>previewTrial(item,b,'full');li.append(b);}if(item.trainedTrialReady){const b=document.createElement('button');b.type='button';b.className='mentor-trial';b.textContent='全部素材训练试听';b.onclick=()=>previewTrial(item,b,'trained');li.append(b);}$('#mentor-saved').append(li);}}const t=d.mentorTraining;if(t){let progress=$('#mentor-training-status');if(!progress){progress=document.createElement('div');progress.id='mentor-training-status';$('#mentor-saved').after(progress);}const caption=document.createElement('p');caption.textContent=t.stage+(t.total?` ${t.step} / ${t.total}`:'')+(t.error?'：'+t.error:'');const bar=document.createElement('progress');bar.max=100;bar.value=Number(t.progress)||0;bar.setAttribute('aria-label','导师音色训练进度');progress.replaceChildren(caption,bar);if(!['complete','failed'].includes(t.status))setTimeout(list,5000);}}catch(e){say(e.message||'暂时无法读取已保存素材。');}}
 $('#mentor-file').onchange=()=>{file=$('#mentor-file').files[0]||null;uploaded=false;uploadId='';if(objectURL)URL.revokeObjectURL(objectURL);$('#mentor-preview').pause();$('#mentor-preview').hidden=true;if(file){if(file.size>200*1024*1024||file.size<1000){say('请选择1KB至200MB的音频或视频。');file=null;}else{objectURL=URL.createObjectURL(file);$('#mentor-preview').src=objectURL;$('#mentor-preview').hidden=false;$('#mentor-filename').textContent=`${file.name} / ${(file.size/1024/1024).toFixed(1)} MB`;say('可先试听，确认授权后直接上传，不必填写前言。');}}controls();};
 $('#mentor-preface').oninput=()=>{localStorage.setItem(draftKey,$('#mentor-preface').value);uploaded=false;uploadId='';controls();};$('#mentor-consent').onchange=controls;
 function request(path,body,headers,onprogress){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST',path);x.timeout=120000;for(const [k,v] of Object.entries({'X-Voice-Upload':uploadId,...headers}))x.setRequestHeader(k,v);x.upload.onprogress=e=>{if(e.lengthComputable)onprogress?.(e.loaded);};x.onload=()=>{let d;try{d=JSON.parse(x.responseText);}catch{}if(x.status>=200&&x.status<300)resolve(d);else reject(Error(d?.error||`保存失败（${x.status}），请重试。`));};x.onerror=x.ontimeout=()=>reject(Error('连接中断，已传分段保留。请点击保存重试。'));x.send(body);});}
 $('#mentor-upload').onclick=async()=>{if(busy)return;if(!file){say('请先点“选择音频或视频”，选好导师素材后再上传。');$('#mentor-file').click();return;}if(!$('#mentor-consent').checked){say('请先勾选导师授权确认，确认后即可上传。');$('#mentor-consent').focus({preventScroll:true});return;}if(uploaded){say('这一份素材已经保存。');return;}busy=true;controls();$('#mentor-preview').pause();$('#mentor-progress-wrap').hidden=false;if(!uploadId){const random=new Uint8Array(16);crypto.getRandomValues(random);uploadId=Array.from(random,v=>v.toString(16).padStart(2,'0')).join('');}
 try{const size=1024*1024,total=Math.ceil(file.size/size);for(let i=0;i<total;i++){say(`正在上传 ${file.name}，第 ${i+1} / ${total} 段`);await request('/api/voice-reference/mentor/chunk',file.slice(i*size,(i+1)*size),{'Content-Type':'application/octet-stream','X-Voice-Chunk':String(i)},loaded=>{const n=Math.min(99,Math.floor((i*size+loaded)/file.size*100));$('#mentor-progress').value=n;$('#mentor-percent').textContent=`${n}%`;});}say('上传完成，正在保存素材…');await request('/api/voice-reference/mentor/complete',JSON.stringify({name:file.name,chunks:total,text:$('#mentor-preface').value,consent:$('#mentor-consent').checked,prefaceMode:'per-mentor',backgroundMusic:'needs-review'}),{'Content-Type':'application/json'});uploaded=true;$('#mentor-progress').value=100;$('#mentor-percent').textContent='已保存';await list();say('导师素材已保存。待检查背景音乐、挑选清晰人声；个性化前言另行准备。');}catch(e){say(e.message);}finally{busy=false;controls();}};
 addEventListener('beforeunload',e=>{if(busy){e.preventDefault();e.returnValue='';}});controls();void list();
}
